import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadAnton = makeLoadFont('Anton');

// Load the heavy, condensed gaming-style font
const { fontFamily: antonFamily } = loadAnton();



export type PlayerOverlaysProps = Record<string, any>;

// SVG Crown Component with black outline and gold fill (outer white glow removed)
const Crown: React.FC<{ s: number }> = ({ s }) => {
  return (
    <svg 
      width={60 * s} 
      height={50 * s} 
      viewBox="0 0 100 80" 
      style={{ overflow: "visible" }}
    >
      {/* Inner Black Stroke & Gold Fill */}
      <g stroke="black" strokeWidth="6" strokeLinejoin="round" fill="#FFD700">
        <path d="M10,65 L90,65 L80,25 L65,45 L50,5 L35,45 L20,25 Z" />
        <circle cx="20" cy="20" r="7" />
        <circle cx="50" cy="0" r="7" />
        <circle cx="80" cy="20" r="7" />
        <rect x="15" y="70" width="70" height="10" rx="4" />
      </g>
    </svg>
  );
};

// The main down arrow badge containing the status text (white outline removed)
const MainBadge: React.FC<{ text: string; color: string; s: number }> = ({ text, color, s }) => {
  return (
    <div style={{ position: "relative", width: 280 * s, height: 110 * s }}>
      <svg width="100%" height="100%" viewBox="0 0 300 110" style={{ position: "absolute", overflow: "visible" }}>
        {/* Base polygon (Down Arrow shape) with black fill */}
        <polygon
          points="40,10 260,10 260,55 295,55 150,105 5,55 40,55"
          fill="black"
        />
      </svg>
      {/* Centered text container, shifted slightly up to fit inside the shaft */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          paddingBottom: 25 * s, 
          paddingTop: 5 * s,
        }}
      >
        <span
          style={{
            fontFamily: antonFamily,
            fontSize: 52 * s,
            color: color,
            lineHeight: 1,
            letterSpacing: 1 * s,
            WebkitTextStroke: `${1.5 * s}px ${color}`,
          }}
        >
          {text}
        </span>
      </div>
    </div>
  );
};

const PlayerOverlay: React.FC<{
  backgroundColor?: string;
  transparentBackground?: boolean;
  durationInSeconds?: number;
  globalYPosition?: number;
  items?: PlayerOverlaysProps["items"];
}> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10,
  globalYPosition = 25,
  items = [
    { id: "p1", mainText: "BEST", textColor: "#00FF33", hasCrown: true, xPercent: 20, delayFrames: 10 },
    { id: "p2", mainText: "BETTER", textColor: "#FFEA00", hasCrown: false, xPercent: 50, delayFrames: 25 },
    { id: "p3", mainText: "BAD", textColor: "#FF0033", hasCrown: false, xPercent: 80, delayFrames: 40 },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080; 

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {items.map((item) => {
        const isVisible = frame >= item.delayFrames;
        
        // Spring entrance for each badge
        const popScale = spring({
          frame: frame - item.delayFrames,
          fps,
          config: { damping: 12, stiffness: 200, mass: 0.8 },
        });

        // Subtle continuous float after entrance
        const floatY = isVisible ? Math.sin((frame - item.delayFrames) / 20) * 8 * s : 0;

        return (
          <div
            key={item.id}
            style={{
              position: "absolute",
              left: `${item.xPercent}%`,
              top: `${globalYPosition}%`,
              // Ensure elements are fully hidden before they animate in
              opacity: isVisible ? 1 : 0,
              // Transform origins handle positioning the center directly on the coordinates
              transform: `translateX(-50%) translateY(-50%) scale(${isVisible ? popScale : 0}) translateY(${floatY}px)`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              transition: "none",
            }}
          >
            {item.hasCrown && (
              <div
                style={{
                  position: "absolute",
                  top: -35 * s,
                  left: 20 * s,
                  zIndex: 10,
                  transform: "rotate(-15deg)",
                }}
              >
                <Crown s={s} />
              </div>
            )}
            
            <MainBadge text={item.mainText} color={item.textColor} s={s} />
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default PlayerOverlay;